mapper.select:
SELECT problem_name, problem_nick_name, tags, difficulty, 0 AS accepted
FROM problem

ORDER BY ${order}
LIMIT #{start}, #{limit}

SELECT public > 0 AS publicProblem, show_solution > 0 AS showSolution, case_amount
FROM problem
WHERE problem_name = #{problemName}

mapper.update:
UPDATE problem
SET case_amount = case_amount + 1
WHERE problem_name = #{problemName}

